<?php
date_default_timezone_set('Asia/Shanghai');
$cfg = parse_ini_file('D:/erp/erp.sdjiantan.com/.env', true)['database'];
$pdo = new PDO("mysql:host={$cfg['hostname']};port={$cfg['hostport']};dbname={$cfg['database']};charset=utf8mb4", $cfg['username'], $cfg['password'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$pdo->exec('SET SESSION TRANSACTION READ ONLY');
$pdo->beginTransaction();
$q = fn($sql) => $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);
$start = strtotime('2026-11-01 00:00:00');
$end = strtotime('2026-11-08 00:00:00');
$worktimes = $q("SELECT w.id,w.admin_id,CAST(w.nums AS DECIMAL(11,2)) hours,w.content,w.createtime,w.step,w.order_id,a.nickname,a.username FROM jt_works_worktime w LEFT JOIN jt_admin a ON a.id=w.admin_id WHERE w.createtime >= $start AND w.createtime < $end ORDER BY w.createtime,w.id");
$logs = $q("SELECT id,order_id,createtime,admin_id,content,CAST(use_time AS DECIMAL(10,2)) hours,work_product_id FROM jt_works_order_logs WHERE createtime >= ".($start-1)." AND createtime < ".($end+1)." AND (use_time IS NOT NULL OR content LIKE '%已完成工序%') ORDER BY createtime,id");
$ids = array_values(array_unique(array_map(fn($w)=>(int)$w['order_id'],$worktimes)));
$productIds = array_values(array_unique(array_merge(array_filter(array_column($logs,'work_product_id')),array_map(fn($w)=>(int)$w['order_id'],array_filter($worktimes,fn($w)=>str_contains($w['content'],'设备编号'))))));
$filter = implode(',', $ids ?: [0]);
$pf = implode(',', $productIds ?: [0]);
$products = $q("SELECT p.id,p.works_order_id,p.sku_id,p.name,p.amount,p.device_sn,s.sku_name,s.goods_name,s.measureunit,s.productmodel FROM jt_works_order_product p LEFT JOIN jt_product_goods_sku s ON s.id=p.sku_id WHERE p.works_order_id IN ($filter) OR p.id IN ($pf) ORDER BY p.works_order_id,p.id");
$ids = array_values(array_unique(array_merge($ids,array_column($products,'works_order_id'))));
$filter = implode(',',array_filter($ids) ?: [0]);
$orders = $q("SELECT id,works_no,order_no,type,status FROM jt_works_order WHERE id IN ($filter) ORDER BY id");
$control = $q("SELECT COUNT(*) records, COUNT(DISTINCT admin_id) people, SUM(CAST(nums AS DECIMAL(11,2))) hours FROM jt_works_worktime WHERE createtime >= $start AND createtime < $end")[0];
$out = ['source'=>'本机旧ERP jiantan_erp','captured_at'=>date('c'),'start'=>$start,'end_exclusive'=>$end,'worktimes'=>$worktimes,'logs'=>$logs,'products'=>$products,'orders'=>$orders,'control'=>$control];
$pdo->rollBack();
file_put_contents(__DIR__.'/source.json',json_encode($out,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));
echo json_encode(['control'=>$control,'logs'=>count($logs),'products'=>count($products),'orders'=>count($orders),'product_branch'=>count($productIds)],JSON_UNESCAPED_UNICODE),PHP_EOL;
